function details(item){show(esc(item.name),`<div class="detail-body">${item.image?`<img src="${esc(item.image)}" alt="">`:''}<p>${[item.place,item.year].filter(Boolean).map(esc).join(' · ')}</p><p>${esc(item.story)}</p>${item.noTrade?`<p class="tag">${txt('非換品','Not for trade')}</p>`:''}<div class="dialog-actions"><button class="button primary" data-action="edit" data-value="${esc(item.id)}">${txt('編輯','Edit')}</button><button class="button outline" data-action="confirm-delete" data-value="${esc(item.id)}">${txt('刪除','Delete')}</button></div></div>`);}
async function refresh(){try{items=await readItems();dataError=false;}catch{dataError=true;}}
